-- DECISION: no DELETE for the runtime (skills have it from 0002; nothing here needs it): an
-- automation is retired by its status, and its versions are history (CLAUDE.md invariant 3).
GRANT SELECT, INSERT, UPDATE ON automation, automation_version TO cs_runtime;
