-- The templates' policy (0002): a client's rows in its own scope; shared rows (tenant_id null) only
-- in operator sessions.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['automation', 'automation_version'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids()) OR (tenant_id IS NULL AND app_is_operator())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()) OR (tenant_id IS NULL AND app_is_operator()))',
      t);
  END LOOP;
END
$$;
--> statement-breakpoint
-- Immutable history (CLAUDE.md invariant 3): only the status changes; DELETE is refused.
CREATE TRIGGER automation_version_immutable BEFORE UPDATE OR DELETE ON automation_version
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('status');
